alter table public.tickets add column if not exists department_id uuid, add column if not exists team_id uuid;
alter table public.ticket_assignments add column if not exists department_id uuid, add column if not exists team_id uuid;
alter table public.ticket_attachments add column if not exists comment_id uuid;
create table if not exists public.ticket_resolutions (id uuid primary key default gen_random_uuid(),ticket_id uuid not null references public.tickets(id) on delete cascade,resolved_by uuid not null references public.profiles(id),resolution_type text not null default 'fixed',resolution_summary text not null,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),constraint ticket_resolutions_type_check check (resolution_type in ('fixed','workaround','duplicate','not_reproducible','not_a_problem','cancelled','other')));
create unique index if not exists ticket_resolutions_ticket_unique on public.ticket_resolutions(ticket_id);
create table if not exists public.ticket_escalations (id uuid primary key default gen_random_uuid(),ticket_id uuid not null references public.tickets(id) on delete cascade,from_level integer not null default 1,to_level integer not null,escalated_by uuid not null references public.profiles(id),reason text not null,note text,created_at timestamptz not null default now(),resolved_at timestamptz,constraint ticket_escalations_level_check check (from_level >= 1 and to_level > from_level));
create index if not exists idx_ticket_escalations_ticket_created on public.ticket_escalations(ticket_id,created_at desc);
create table if not exists public.ticket_watchers (ticket_id uuid not null references public.tickets(id) on delete cascade,user_id uuid not null references public.profiles(id) on delete cascade,added_by uuid not null references public.profiles(id),created_at timestamptz not null default now(),primary key(ticket_id,user_id));
alter table public.tickets add constraint tickets_department_fk foreign key (department_id) references public.departments(id);
alter table public.tickets add constraint tickets_team_fk foreign key (team_id) references public.teams(id);
alter table public.ticket_assignments add constraint ticket_assignments_department_fk foreign key (department_id) references public.departments(id);
alter table public.ticket_assignments add constraint ticket_assignments_team_fk foreign key (team_id) references public.teams(id);
alter table public.ticket_attachments add constraint ticket_attachments_comment_fk foreign key (comment_id) references public.ticket_comments(id) on delete set null;
create index if not exists idx_tickets_company_department_status on public.tickets(company_id,department_id,status,created_at desc);
create index if not exists idx_tickets_company_team_status on public.tickets(company_id,team_id,status,created_at desc);
create index if not exists idx_tickets_unassigned on public.tickets(company_id,priority,created_at desc) where status not in ('resolved','closed');
create index if not exists idx_ticket_watchers_user on public.ticket_watchers(user_id,created_at desc);
create or replace function private.can_view_ticket(p_ticket_id uuid) returns boolean language sql stable security definer set search_path=public,pg_catalog as $$ select exists(select 1 from tickets t where t.id=p_ticket_id and (private.has_company_role(t.company_id,array['admin'::membership_role,'hr'::membership_role,'manager'::membership_role]) or t.requester_id=auth.uid() or t.created_by=auth.uid() or exists(select 1 from ticket_assignments ta where ta.ticket_id=t.id and ta.assignee_id=auth.uid() and ta.unassigned_at is null) or exists(select 1 from ticket_assignments ta join team_members tm on tm.team_id=ta.team_id and tm.user_id=auth.uid() where ta.ticket_id=t.id and ta.unassigned_at is null) or exists(select 1 from ticket_watchers tw where tw.ticket_id=t.id and tw.user_id=auth.uid()))); $$;
create or replace function private.can_manage_ticket(p_ticket_id uuid) returns boolean language sql stable security definer set search_path=public,pg_catalog as $$ select exists(select 1 from tickets t where t.id=p_ticket_id and (private.has_company_role(t.company_id,array['admin'::membership_role,'hr'::membership_role,'manager'::membership_role]) or exists(select 1 from ticket_assignments ta where ta.ticket_id=t.id and ta.assignee_id=auth.uid() and ta.unassigned_at is null) or exists(select 1 from ticket_assignments ta join team_members tm on tm.team_id=ta.team_id and tm.user_id=auth.uid() where ta.ticket_id=t.id and ta.unassigned_at is null))); $$;
alter table public.tickets enable row level security;alter table public.ticket_comments enable row level security;alter table public.ticket_status_history enable row level security;alter table public.ticket_assignments enable row level security;alter table public.ticket_attachments enable row level security;alter table public.asset_tickets enable row level security;alter table public.ticket_categories enable row level security;alter table public.ticket_resolutions enable row level security;alter table public.ticket_escalations enable row level security;alter table public.ticket_watchers enable row level security;
drop policy if exists tickets_select_member on public.tickets;drop policy if exists ticket_comments_select_member on public.ticket_comments;drop policy if exists ticket_comments_insert_member on public.ticket_comments;drop policy if exists ticket_status_history_select_member on public.ticket_status_history;drop policy if exists ticket_status_history_insert_manager on public.ticket_status_history;drop policy if exists ticket_assignments_select_member on public.ticket_assignments;drop policy if exists ticket_attachments_select_member on public.ticket_attachments;drop policy if exists ticket_attachments_insert_member on public.ticket_attachments;
create policy tickets_select_authorized on public.tickets for select to authenticated using(private.can_view_ticket(id));
create policy ticket_status_history_select_authorized on public.ticket_status_history for select to authenticated using(private.can_view_ticket(ticket_id));
create policy ticket_status_history_insert_authorized on public.ticket_status_history for insert to authenticated with check(changed_by=auth.uid() and private.can_manage_ticket(ticket_id));
create policy ticket_comments_select_authorized on public.ticket_comments for select to authenticated using(private.can_view_ticket(ticket_id) and (comment_type='public'::ticket_comment_type or private.can_manage_ticket(ticket_id)));
create policy ticket_comments_insert_authorized on public.ticket_comments for insert to authenticated with check(author_id=auth.uid() and private.can_view_ticket(ticket_id) and (comment_type='public'::ticket_comment_type or private.can_manage_ticket(ticket_id)));
create policy ticket_assignments_select_authorized on public.ticket_assignments for select to authenticated using(private.can_view_ticket(ticket_id));
create policy ticket_attachments_select_authorized on public.ticket_attachments for select to authenticated using(private.can_view_ticket(ticket_id));
create policy ticket_resolutions_select_authorized on public.ticket_resolutions for select to authenticated using(private.can_view_ticket(ticket_id));
create policy ticket_resolutions_insert_authorized on public.ticket_resolutions for insert to authenticated with check(resolved_by=auth.uid() and private.can_manage_ticket(ticket_id));
create policy ticket_resolutions_update_authorized on public.ticket_resolutions for update to authenticated using(private.can_manage_ticket(ticket_id)) with check(private.can_manage_ticket(ticket_id));
create policy ticket_escalations_select_authorized on public.ticket_escalations for select to authenticated using(private.can_view_ticket(ticket_id));
create policy ticket_escalations_insert_authorized on public.ticket_escalations for insert to authenticated with check(escalated_by=auth.uid() and private.can_manage_ticket(ticket_id));
create policy ticket_watchers_select_authorized on public.ticket_watchers for select to authenticated using(private.can_view_ticket(ticket_id));
create policy ticket_watchers_insert_authorized on public.ticket_watchers for insert to authenticated with check(added_by=auth.uid() and private.can_view_ticket(ticket_id));
create policy ticket_watchers_delete_authorized on public.ticket_watchers for delete to authenticated using(user_id=auth.uid() or private.has_company_role((select company_id from tickets where id=ticket_id),array['admin'::membership_role,'hr'::membership_role,'manager'::membership_role]));
